from collections import defaultdict
from functools import lru_cache
S=input()
rep_table=set()
inf = 10**9
pos = [defaultdict(list) for _ in range(len(S))]
for i in range(1,len(S)+1):
    #長さを固定
    lis = [0 for _ in range(len(S))]
    for j in range(len(S)-2*i+1,-1,-1):
        if S[j:j+i] == S[j+i:j+2*i]:
            lis[j] = max(i,lis[j+i])+(i)
            for k in range(lis[j],i,-i):
                pos[j][k].append(i)



edge = [[[] for _ in range(len(S))] for _ in range(len(S))]

@lru_cache(maxsize=10**7)
def solve(i,j):
    if i == j:
        edge[i][j] = [S[i]]
        return 1
    fle = 10**18
    fres = []
    for k in range(i+1,j+1):
        res = solve(i,k-1)
        res2 = solve(k,j)
        if res + res2 <= fle:
            fle = res + res2
            fres = [(i,k-1),(k,j)]
    for a in pos[i][j-i+1]:
        if (j-i+1)//a >= 10:
            continue
        res = solve(i,i+a-1) + 2 + len(str((j-i+1)//a))
        #print(i,j,a,'->',res)
        if res < fle:
            fle = res
            fres = [str((j-i+1)//a),"(",(i,i+a-1),")"]
    edge[i][j] = fres    
    return fle

ans = []
def make(i,j):
    for e in edge[i][j]:
        if type(e) == tuple:
            make(e[0],e[1])
        else:
            ans.append(e)

