N, M = map(int, input().split())
X = [input() for i in range(N)]
root = (-1, -1)
for i in range(N):
    for j in range(M):
        if X[i][j] == "P":
            root = (i, j)


def dfs(u, p):
    i, j = u
    l = []
    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if not 0 <= i + di < N:
            continue
        if not 0 <= j + dj < M:
            continue
        if X[i + di][j + dj] == ".":
            continue
        if (i + di, j + dj) == p:
            continue
        l.append(dfs((i + di, j + dj), u))
    if X[i][j] == "P" or X[i][j] == "#":
        assert len(l) == 1
        return l[0]
    elif X[i][j].isdigit():
        assert len(l) == 0
        return int(X[i][j])
    else:
        assert len(l) == 2
        l.sort()
        if X[i][j] == "+":
            return l[0] + l[1]
        elif X[i][j] == "-":
            return l[1] - l[0]
        elif X[i][j] == "*":
            return l[0] * l[1]
        else:
            return l[1] // l[0]


