import sys
import math
import random
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0

    MAXV = 10**6
    spf = list(range(MAXV + 1))
    for i in range(2, int(math.isqrt(MAXV)) + 1):
        if spf[i] == i:
            for j in range(i * i, MAXV + 1, i):
                if spf[j] == j:
                    spf[j] = i

    H = {}
    rng = random.Random()

    def sf(x):
        r = 0
        if x == 1:
            return r
        while x > 1:
            p = spf[x]
            c = 0
            while x % p == 0:
                c += 1
                x = x // p
            if c % 2 == 1:
                if p not in H:
                    H[p] = rng.getrandbits(64)
                r ^= H[p]
        return r

    N = int(input[ptr])
    ptr += 1

    A = []
    for r in range(1, N):
        row = list(map(int, input[ptr:ptr + r]))
        ptr += r
        A.append(row)

    B = []
    for r in range(1, N):
        row = list(map(int, input[ptr:ptr + r]))
        ptr += r
        B.append(row)

    C = []
    for r in range(2, N + 1):
        row = list(map(int, input[ptr:ptr + (r - 1)]))
        ptr += (r - 1)
        C.append(row)

    tot = N * (N + 1) // 2

    def idx(r, p):
        return r * (r + 1) // 2 + p

    g = [[] for _ in range(tot)]

    for r in range(N - 1):
        for j in range(r + 1):
            u = idx(r, j)
            v = idx(r + 1, j)
            w = sf(A[r][j])
            g[u].append((v, w))
            g[v].append((u, w))

    for r in range(N - 1):
        for j in range(r + 1):
            u = idx(r, j)
            v = idx(r + 1, j + 1)
            w = sf(B[r][j])
            g[u].append((v, w))
            g[v].append((u, w))

    for r in range(1, N):
        for j in range(r):
            u = idx(r, j)
            v = idx(r, j + 1)
            w = sf(C[r - 1][j])
            g[u].append((v, w))
            g[v].append((u, w))

    vis = [False] * tot
    f = [0] * tot
    ans = 0

    for s in range(tot):
        if not vis[s]:
            comp = []
            ok = True
            q = deque()
            q.append(s)
            vis[s] = True
            f[s] = 0
            comp.append(s)
            while q:
                u = q.popleft()
                for (v, w) in g[u]:
                    nv = f[u] ^ w
                    if not vis[v]:
                        vis[v] = True
                        f[v] = nv
                        q.append(v)
                        comp.append(v)
                    elif f[v] != nv:
                        ok = False
            if ok:
                cnt = {}
                for v in comp:
                    cnt[f[v]] = cnt.get(f[v], 0) + 1
                for m in cnt.values():
                    ans += m * (m - 1) // 2

    print(ans)

if __name__ == '__main__':
    main()

import sys
from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Find the starting position 'S'
    start_r, start_c = -1, -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start_r, start_c = i, j
                break
        if start_r != -1:
            break

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS to find the connected component of 'S' (component_id=1)
    component_id = [[0] * W for _ in range(H)]
    q = deque()
    q.append((start_r, start_c))
    component_id[start_r][start_c] = 1
    C_size = 1

    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if (grid[nr][nc] == '.' or grid[nr][nc] == 'S') and component_id[nr][nc] == 0:
                    component_id[nr][nc] = 1
                    C_size += 1
                    q.append((nr, nc))

    # Assign component_ids to other connected components
    current_id = 2
    component_size = [0, C_size]  # component_id starts from 1

    for i in range(H):
        for j in range(W):
            if (grid[i][j] == '.' or grid[i][j] == 'S') and component_id[i][j] == 0:
                # BFS for new component
                q = deque()
                q.append((i, j))
                component_id[i][j] = current_id
                size = 1
                while q:
                    r, c = q.popleft()
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if (grid[nr][nc] == '.' or grid[nr][nc] == 'S') and component_id[nr][nc] == 0:
                                component_id[nr][nc] = current_id
                                size += 1
                                q.append((nr, nc))
                component_size.append(size)
                current_id += 1

    total_components = current_id
    last_seen = [0] * total_components
    wall_number = 0
    max_reachable = C_size

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                adjacent_to_C = False
                # Check if this wall is adjacent to component 1
                for dr, dc in directions:
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < H and 0 <= nj < W:
                        if component_id[ni][nj] == 1:
                            adjacent_to_C = True
                            break
                if adjacent_to_C:
                    wall_number += 1
                    sum_other = 0
                    for dr, dc in directions:
                        ni, nj = i + dr, j + dc
                        if 0 <= ni < H and 0 <= nj < W:
                            cid = component_id[ni][nj]
                            if cid > 1 and last_seen[cid] != wall_number:
                                sum_other += component_size[cid]
                                last_seen[cid] = wall_number
                    # Include the wall cell itself
                    total = C_size + 1 + sum_other
                    if total > max_reachable:
                        max_reachable = total

    print(max_reachable)

if __name__ == '__main__':
    main()

import sys
from collections import defaultdict

MOD = 998244353

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    F = list(map(int, input[ptr:ptr+N]))
    ptr += N
    F = [0] + F  # 1-based indexing

    # Build inverse mapping
    inv = defaultdict(list)
    for i in range(1, N+1):
        inv[F[i]].append(i)

    # Detect cycles
    col = [0] * (N + 1)
    cyc = [False] * (N + 1)
    cl = [0] * (N + 1)
    cycList = []

    for i in range(1, N+1):
        if col[i] == 0:
            stack = []
            cur = i
            while True:
                if col[cur] == 0:
                    col[cur] = 1
                    stack.append(cur)
                    cur = F[cur]
                elif col[cur] == 1:
                    idx = -1
                    for j in range(len(stack)):
                        if stack[j] == cur:
                            idx = j
                            break
                    L = len(stack) - idx
                    cycV = []
                    for j in range(idx, len(stack)):
                        u = stack[j]
                        cyc[u] = True
                        cl[u] = L
                        cycV.append(u)
                    cycList.append(cycV)
                    for u in stack:
                        col[u] = 2
                    break
                else:
                    for u in stack:
                        col[u] = 2
                    break

    # Build children for tree parts
    ch = [[] for _ in range(N+1)]
    for i in range(1, N+1):
        if not cyc[i]:
            p = F[i]
            ch[p].append(i)

    # DP tables
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    dpDone = [False] * (N + 1)

    def dfsDP(v):
        for w in ch[v]:
            dfsDP(w)
        for x in range(1, N + 1):
            total = 0
            for u in inv[x]:
                product = 1
                for w in ch[v]:
                    product = (product * dp[w][u]) % MOD
                total = (total + product) % MOD
            dp[v][x] = total
        dpDone[v] = True

    for i in range(1, N + 1):
        if not cyc[i] and not dpDone[i]:
            dfsDP(i)

    def Fval(v, x):
        product = 1
        for w in ch[v]:
            product = (product * dp[w][x]) % MOD
        return product

    ans = 1
    for cycV in cycList:
        start = cycV[0]
        dC = []
        cur = start
        while True:
            dC.append(cur)
            cur = F[cur]
            if cur == start:
                break
        L = len(dC)

        sumC = 0
        for a in range(1, N + 1):
            if not cyc[a]:
                continue
            if L % cl[a] != 0:
                continue
            product = 1
            t = a
            for i in range(L):
                product = (product * Fval(dC[i], t)) % MOD
                t = F[t]
            sumC = (sumC + product) % MOD
        ans = (ans * sumC) % MOD

    print(ans)

if __name__ == '__main__':
    main()

import sys

def g(x):
    while x & 1:
        if x == 1:
            return 0
        x = (x - 1) >> 1
    return x >> 1

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        n = int(input[ptr])
        m = int(input[ptr + 1])
        ptr += 2
        gn = g(n)
        gm = g(m)
        if gn ^ gm:
            print("First")
        else:
            print("Second")

