def num_sum(n):
  res = 0
  while n > 0:
    res += n%10
    n = n//10
  return res

def find(n):
  for i in range(n, 2*n):
    if i%num_sum(i) == 0 and (i+1)%num_sum(i+1) == 0:
      return i
  return -1

