def func(k, i):
    if k == 0:
        return A[i], 1
    v1, c1 = func(k - 1, 3 * i)
    v2, c2 = func(k - 1, 3 * i + 1)
    v3, c3 = func(k - 1, 3 * i + 2)
    if v1 == v2 == v3:
        return v1, c1 + c2 + c3 - max(c1, c2, c3)
    elif v1 == v2:
        return v1, min(c1, c2)
    elif v2 == v3:
        return v2, min(c2, c3)
    elif v3 == v1:
        return v3, min(c3, c1)


