def find_answer(N, K, A):
    M = max(A)

    s = [0] * (M + 1)
    for num in A:
        s[num] += 1

    t = [0] * (M + 1)
    for d in range(1, M + 1):
        for n in range(d, M + 1, d):
            t[d] += s[n]

    u = [0] * (M + 1)
    for d in range(1, M + 1):
        if t[d] < K:
            continue
        for n in range(d, M + 1, d):
            u[n] = max(u[n], d)

    return [u[num] for num in A]


