       self.children = {}
       self.value = 0

def find(node, key):
    for c in key:
        if c not in node.children:
            return False
        node = node.children[c]
    return node.value

def insertx(node, key):
    global ans
    for c in key:
        if c not in node.children:
            node.children[c] = Node()
        node = node.children[c]

    q = deque()
    q.append(node)
    while q:
        node = q.popleft()
        if node.value >= 1:
            ans -= node.value
        node.value = -1
        for c in node.children.keys():
            nextnode = node.children[c]
            if nextnode.value == -1:
                continue

            q.append(nextnode)
    return

def inserty(node, key):
    global ans
    for c in key:
        #print(node.children, node.value)
        if node.value == -1:
            return
        elif c not in node.children:
            node.children[c] = Node()

        node = node.children[c]

    if node.value != -1:
        node.value += 1 #B
        ans += 1
    return


