import sys

def main():
    pow9 = [1]  # pow9[i] = 9^i
    for i in range(1, 40):
        pow9.append(pow9[-1] * 9)

    T = int(sys.stdin.readline())
    for _ in range(T):
        K = int(sys.stdin.readline())
        if K <= 9:
            print(K)
            continue

        # Find L
        L = 1
        while (9**(L + 1) - 9) // 8 < K:
            L += 1

        sum_prev = (9**L - 9) // 8
        M = K - sum_prev

        # Generate the M-th Neq number with length L
        number = []
        prev = None
        for pos in range(L):
            if pos == 0:
                possible = list(range(1, 10))
            else:
                possible = []
                for d in range(10):
                    if d != prev:
                        possible.append(d)
            for d in possible:
                remaining = L - pos - 1
                cnt = pow9[remaining]
                if cnt < M:
                    M -= cnt
                else:
                    number.append(str(d))
                    prev = d
                    break
        print(''.join(number))

