import math

n = int(input())
points = [tuple(map(int, input().split())) for _ in range(n)]

if n < 3:
    print(0)
    exit()

max_colinear = 0

for i in range(n):
    p = points[i]
    slopes = {}
    for j in range(n):
        if i == j:
            continue
        dx = points[j][0] - p[0]
        dy = points[j][1] - p[1]
        if dx == 0:
            slope = (0, 1)
        elif dy == 0:
            slope = (1, 0)
        else:
            gcd_val = math.gcd(abs(dx), abs(dy))
            dx_reduced = dx // gcd_val
            dy_reduced = dy // gcd_val
            if dx_reduced < 0:
                dx_reduced *= -1
                dy_reduced *= -1
            slope = (dx_reduced, dy_reduced)
        if slope in slopes:
            slopes[slope] += 1
        else:
            slopes[slope] = 1
    current_max = max(slopes.values(), default=0) + 1
    if current_max > max_colinear:
        max_colinear = current_max

M = max_colinear
K = n - M

if M > 2 * K:
    print(K)
else:
    print(n // 3)

