from types import GeneratorType


def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        else:
            to = f(*args, **kwargs)
            while True:
                if type(to) is GeneratorType:
                    stack.append(to)
                    to = next(to)
                else:
                    stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(to)
            return to

    return wrappedfunc

mod=10**9+7
farr=[1]
ifa=[]

def fact(x,mod=0):
    if mod:
        while x>=len(farr):
            farr.append(farr[-1]*len(farr)%mod)
    else:
        while x>=len(farr):
            farr.append(farr[-1]*len(farr))
    return farr[x]

def ifact(x,mod):
    global ifa
    fact(x,mod)
    ifa.append(pow(farr[-1],mod-2,mod))
    for i in range(x,0,-1):
        ifa.append(ifa[-1]*i%mod)
    ifa.reverse()

def per(i,j,mod=0):
    if i<j: return 0
    if not mod:
        return fact(i)//fact(i-j)
    if i>len(farr):
        res=1
        if j>i-j:j=i-j
        for x in range(i,i-j,-1):
            res=res*x%mod
        return res
    else:
        res=farr[i]
        return res*ifa[i-j]%mod

def com(i,j,mod=0):
    if i<j: return 0
    if not mod:        
        return per(i,j)//fact(j)
    if j>i-j:j=i-j
    return per(i,j,mod)*ifa[j]%mod

def catalan(n):
    return com(2*n,n)//(n+1)

def matrixmul(a,b,mod):
    return [[sum(x*y for x,y in zip(row,col))%mod for col in zip(*b)]for row in a]

def mpow(n,a,k,mod):
    mul=a
    res=None
    while k:
        if k&1:
            if res==None:
                res=mul
            else:
                res=matrixmul(res,mul,mod)
        k>>=1
        mul=matrixmul(mul,mul,mod)
    return res

def inverse(a,m):
    a%=m
    if a<=1: return a
    return ((1-inverse(m,a)*m)//a)%m

def exgcd(a,b):
    if b==0:
        return 1,0,a
    x,y,g=exgcd(b,a%b)
    x,y=y,(x-a//b*y)
    return x,y,g

