############################################data structure
class BIT:
    __slots__=('n','arr')
    def __init__(self,n):
        self.n=n 
        self.arr=[0]*n        
    def update(self,x,v):
        while x<self.n:
            self.arr[x]+=v
            x+=x&-x
    def query(self,x):
        ans=0
        while x:
            ans+=self.arr[x]
            x&=x-1
        return ans
    def prod(self,l,r):
        return self.query(r)-self.query(l-1)
    def display(self):
        print([self.query(i) for i in range(1,self.n)])

class SparseTable:
    __slots__=('n','st','e','mx','op')
    def __init__(self,op,e,arr):#n!=0
        n=len(arr)
        mx=n.bit_length()#取不到
        self.op=op
        self.e=e
        self.st=[[0]*mx for i in range(n)]
        for i in range(n):
            self.st[i][0]=arr[i]
        for j in range(1,mx):
            for i in range(n-(1<<j)+1):
                self.st[i][j]=op(self.st[i][j-1],self.st[i+(1<<j-1)][j-1])
    def query(self,l,r):
        if l>r:return self.e
        s=(r+1-l).bit_length()-1
        return self.op(self.st[l][s],self.st[r-(1<<s)+1][s])

class TreeAncestor:
    def __init__(self, n, edges):
        mx=n.bit_length()
        self.par=[[-1]*n for _ in range(mx)]
        g = [[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w))
            g[v].append((u,w))
        self.dep=[0]*n
        self.cnt=A2(n,27)
        @bootstrap
        def dfs(u,p):
            self.par[0][u]=p
            for v,w in g[u]:
                if v!=p:
                    cnt[v]=cnt[u].copy()
                    self.dep[v]=dep[u]+1
                    cnt[v][w]+=1
                    yield dfs(v,u)
            yield None
        dfs(0,-1)
        for i in range(mx-1):
            for u in range(n):
                if (p:=self.par[i][u])!=-1:
                    self.par[i+1][u]=self.par[i][p]

    def getKthAncestor(self,node, k):
        for i in range(k.bit_length()):
            if k>>i&1:
                node=self.par[i][node]
                if node<0:break
        return node

    def lca(self,u,v):
        if self.dep[u]<self.dep[v]:
            u,v=v,u
        u=self.getKthAncestor(u,self.dep[u]-self.dep[v])
        if u==v:return u
        for i in range(self.mx-1,-1,-1):
            if self.par[i][u]==self.par[i][v]:continue
            u=self.par[i][u]
            v=self.par[i][v]
        return self.par[0][u]
