def Prime(n):
    c=0
    prime=[]
    flag=[0]*(n+1) 
    for i in range(2,n+1):
        if not flag[i]:
            prime.append(i)
            c+=1
        for j in range(c):
            if i*prime[j]>n: break
            flag[i*prime[j]]=prime[j]
            if i%prime[j]==0: break
    return flag

def rotate(a):#clockwise 90° return tuple
        return list(zip(*reversed(a)))

def lis(nums):
    res=[]
    for k in nums:
        i=bisect_left(res,k)
        if i==len(res):
            res.append(k)
        else:
            res[i]=k
    return len(res)

def RP(nums):#逆序对
    n = len(nums)
    s=set(nums)
    d={}
    for i,k in enumerate(sorted(s),1):
        d[k]=i
    bi=BIT([0]*(len(s)+1))
    ans=0
    for i in range(n-1,-1,-1):
        ans+=bi.query(d[nums[i]]-1)
        bi.update(d[nums[i]],1)
    return ans

def michange(a,b):
    d=defaultdict(deque)
    for i,x in enumerate(b):
        d[x].append(i)
    order=A(len(a))
    for i,x in enumerate(a):
        if not d:
            return -1
        order[i]=d[x].popleft()
    return RP(order)


