def kru(n,e):
    dsu=DSU(n+1)
    e.sort()
    res=0
    cnt=n
    for w,u,v in e:
        if dsu.same(u,v):continue
        dsu.union(u,v)
        res+=w
        cnt-=1
    return res if cnt==1 else inf

def bell(s):#bellman-Ford
    dis=A(n,inf)
    dis[s]=0
    for i in range(n-1):
        for u,v,w in edge:
            if dis[v]>dis[u]+w:
                dis[v]=dis[u]+w
    change=A(n)
    for i in range(n):
        for u,v,w in edge:
            if dis[v]>dis[u]+w:
                dis[v]=dis[u]+w
                change[v]=1
    return dis

def dij(s,graph):
    d=[inf]*n
    d[s]=0
    heap=[(0,s)]
    while heap:
        dis,u=heappop(heap)
        if dis>d[u]:
            continue
        for v,w in graph[u]:
            if d[v]>d[u]+w:
                d[v]=d[u]+w
                heappush(heap,(d[v],v))
    return d

#有向拓扑，编号1-n
def topo(n):
    q=deque()
    res=[]
    for i in range(1,n+1):
        if ind[i]==0:
            q.append(i)
            res.append(i)
    while q:
        u=q.popleft()
        for v in g[u]:
            ind[v]-=1
            if ind[v]==0:
                q.append(v)
                res.append(v)
    return res

def diameter(n,g):
    vis=A(n)
    d=A(n)
    def dfs(u):
        vis[u]=1
        for v in g[u]:
            if not vis[v]:
                d[v]=d[u]+1
                dfs(v)
    dfs(0)
    ma=-1
    for i in range(n):
        if d[i]>ma:
            r=i
            ma=d[i]
    vis=A(n)
    d=A(n)
    dfs(r)
    return max(d)
