def Manacher(s):#(0,0)对应res[2];(0,1)对应res[3];原长对应半径减1
    n=len(s)
    ss=['$','#']
    for x in s:
        ss.append(x)
        ss.append('#')
    ss.append('!')
    res=A(2*n+3,1)
    rm=0
    for i in range(2,2*n+1):
        if i<=rm:
            j=2*im-i
            res[i]=fmin(res[j],rm-i+1)
        while ss[i+res[i]]==ss[i-res[i]]:
            res[i]+=1
        if i+res[i]-1>rm:
            im=i 
            rm=i+res[i]-1
    return res

def z_algorithm(s):
    n = len(s)
    if n == 0:return []
    z = [0]*n
    j = 0
    for i in range(1, n):
        z[i] = 0 if j + z[j] <= i else min(j + z[j] - i, z[i - j])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if j + z[j] < i + z[i]:
            j = i
    z[0] = n
    return z
