def solve(aaa):
    n = len(aaa)
    if n == 0:
        return 0
    if n == 1:
        return 1
    res1 = 0
    res3 = 0
    even0 = []
    even2 = []
    for a in aaa:
        if a & 1:
            if a & 2:
                res3 += 1
            else:
                res1 += 1
        else:
            even0.append(a >> 1)
            even2.append((a + 2) >> 1)
    res1 += solve(even2)
    res3 += solve(even0)
    return max(res1, res3)


