def solve_case(s):
    zeros = ones = 0
    balanced_prefixes = 0

    for ch in s:
        if ch == '0':
            zeros += 1
        else:
            ones += 1
        if zeros == ones:
            balanced_prefixes += 1

    return pow(2, balanced_prefixes)

