    return map(int, input().split())
def solve():
    a = input()
    b = input()
    if len(b)>len(a):
        return -1
    idxes = []
    j = len(b)-1
    for i in range(len(a)-1,-1,-1):
        if a[i] == b[j]:
            idxes.append(i)
            j-=1
            if j == -1:
                break
    ans = 0
    idxes = idxes[::-1]
    if len(idxes)!=len(b):
        return -1
    cur_idx = 1
    j = 0
    for i in range(len(a)):
        if j == len(idxes):
            ans+=cur_idx
            continue
        if i != idxes[j]:
            ans+=cur_idx
        else:
            cur_idx+=1
            j+=1
    return ans

