def sol(n,x,a):
    ms=1
    c=1
    for i in range(1,n):
        if a[i]>=a[i-1]:
            c+=1
        else:
            c=1
        ms=max(ms,c)
    for i in range(n):
        o=a[i]
        a[i]=o*x
        l=i
        while l>0 and a[l-1]<=a[l]:
            l-=1
        r=i
        while r+1<n and a[r]<=a[r+1]:
            r+=1
        s=r-l+1
        ms=max(ms,s)
        a[i]=o
    return ms
