class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        max_ = sum(grid[0])
        flag = 0
        for i in range(1,len(grid)):
            su = sum(grid[i])
            max_ = max(su, max_)
            if max_ == su:
                flag = i
        return flag

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        a, b = nums1[-1], nums2[-1]
        x = 0
        p = False
        for i in range(len(nums1) - 1):
            if nums1[i] <= a and nums2[i] <= b:
                continue
            if nums1[i] > b or nums2[i] > a:
                p = True
                break
            x += 1

        y = 1
        t = False
        for i in range(len(nums1) - 1):
            if nums1[i] <= b and nums2[i] <= a:
                continue
            if nums1[i] > a or nums2[i] > b:
                if p:
                    return -1
                t = True
                break
            y += 1

        return (x if t else y) if p or t else min(x, y)

class Solution:
    def maximumScoreAfterOperations(self, edges: List[List[int]], values: List[int]) -> int:
        n = len(edges)+1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        def dfs(i, p):
            # returns result_if_healthy_ancestor, result_if_no_healthy_ancestor
            if len(adj[i]) == 1 and i != 0:
                # if leaf node, exit early
                return values[i], 0
            if_healthy_ancestor = 0
            if_no_healthy_ancestor = 0
            for j in adj[i]:
                if j == p:
                    continue
                sub_healthy, sub_no_healthy = dfs(j, i)
                if_healthy_ancestor += sub_healthy
                if_no_healthy_ancestor += sub_no_healthy
            return values[i]+if_healthy_ancestor, max(if_healthy_ancestor, values[i]+if_no_healthy_ancestor)

        return dfs(0, -1)[1]

class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        mod = 1000000007

        for i in range(n):
            x = 2 ** i

            if a * b < (a ^ x) * (b ^ x):
                a ^= x
                b ^= x

        return (a * b) % mod

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums = sorted(set(nums))
        res, n = 0, len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] > nums[i] << 1:
                    break
                res = max(res, nums[i] ^ nums[j])
        return res

class Solution:
    def findWordsContaining(self, words: List[str], x: str) -> List[int]:
        ans = []
        for i, word in enumerate(words):
            if x in word:
                ans.append(i)
        return ans

