from typing import List

class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        q = len(queries)
        s1 = s[:n // 2]
        s2 = s[n // 2:][::-1]
        if Counter(s1) != Counter(s2):
            return [False] * q

        for i, query in enumerate(queries):
            queries[i] = [query[0], query[1], n - 1 - query[3], n - 1 - query[2]]

        n //= 2
        left = [-1] * n
        l = -1
        for i in range(n):
            if s1[i] == s2[i]:
                if l == -1:
                    l = i
            else:
                if l != -1:
                    for j in range(l, i):
                        left[j] = i - 1
                    l = -1
        if l != -1:
            for j in range(l, n):
                left[j] = n - 1

        cnt1 = [[0] * 26]
        curr = [0] * 26
        for i in range(n):
            curr[ord(s1[i]) - ord('a')] += 1
            cnt1.append(curr[:])

        cnt2 = [[0] * 26]
        curr = [0] * 26
        for i in range(n):
            curr[ord(s2[i]) - ord('a')] += 1
            cnt2.append(curr[:])

        result = []

        for a, b, c, d in queries:
            flag = True
            if a > c:
                a, b, c, d = c, d, a, b
                flag = False
            if b < c - 1:
                if left[b + 1] >= c - 1 and left[0] >= a - 1 and (d == n - 1 or left[d + 1] == n - 1):
                    curr = [0] * 26
                    total = [0] * 26
                    for i in range(26):
                        curr[i] = cnt2[b + 1][i] - cnt2[a][i]
                        total[i] = cnt1[b + 1][i] - cnt1[a][i]
                        if total[i] < curr[i]:
                            result.append(False)
                            break
                    else:
                        result.append(True)
                else:
                    result.append(False)
            elif b >= d:
                if left[0] >= a - 1 and (b == n - 1 or left[b + 1] == n - 1):
                    result.append(True)
                else:
                    result.append(False)
            else:
                if left[0] >= a - 1 and (d == n - 1 or left[d + 1] == n - 1):
                    curr = [0] * 26
                    total = [0] * 26
                    if flag:
                        for i in range(26):
                            curr[i] = cnt2[c][i] - cnt2[a][i]
                            total[i] = cnt1[b + 1][i] - cnt1[a][i]
                            if total[i] < curr[i]:
                                result.append(False)
                                break
                        else:
                            result.append(True)
                    else:
                        for i in range(26):
                            curr[i] = cnt1[c][i] - cnt1[a][i]
                            total[i] = cnt2[b + 1][i] - cnt2[a][i]
                            if total[i] < curr[i]:
                                result.append(False)
                                break
                        else:
                            result.append(True)
                else:
                    result.append(False)
        return result

class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        lengths=[len(s1),len(s2),len(s3)]

        minimum_length = min(lengths)
        count=0
        for i in range(minimum_length):
            if(s1[i] == s2[i] == s3[i]):
                count+=1
            else:
                break
        if(count==0):
            return -1

        result = sum(length-count for length in lengths)
        return result

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowel_surplus = res = 0
        vowels = set('aeiou')
        for min_valid_len in range(2, 2 * k + 1, 2):
            if (min_valid_len >> 1) ** 2 % k == 0:
                break
        pre = defaultdict(lambda: [0] * min_valid_len)
        pre[0][min_valid_len - 1] = 1
        for i, l in enumerate(s):
            vowel_surplus += 1 if l in vowels else -1
            res += pre[vowel_surplus][i % min_valid_len]
            pre[vowel_surplus][i % min_valid_len] += 1
        return res

class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        prices = [0] + prices
        n = len(prices)
        if n <= 3:
            return prices[1]
        dp = [0] * n
        dp[1] = dp[2] = prices[1]
        q = deque([2])

        for i in range(3, n):
            while q and q[0] * 2 < i:
                q.popleft()

            dp[i] = dp[i - 1] + prices[i]
            if q:
                dp[i] = min(dp[i], dp[q[0] - 1] + prices[q[0]])

            while q and dp[q[-1] - 1] + prices[q[-1]] >= dp[i - 1] + prices[i]:
                q.pop()
            q.append(i)

        return dp[-1]

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        X = 1
        while X * X % k != 0:
            X += 1
        s += 'x'
        length = len(s)
        ans = 0
        count = 0
        m = Counter()
        for preLen in range(0, length):
            key = (count, preLen % (2 * X))
            ans += m[key]
            m[key] += 1
            if s[preLen] in "aeiou":
                count += 1
            else:
                count -= 1
        return ans

class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        dc = {}
        n = len(nums)
        for i in range(n):
            dc[nums[i]]=i

        i = 0
        j = dc[nums[0]]
        part = 0
        while j<n:
            if i<=j:
                if dc[nums[i]]>j:
                    j=dc[nums[i]]
                else:
                    i+=1
            else:
                part+=1
                j+=1
        return 2**(part-1) % (10**9+7)

class Solution(object):
    def countSubarrays(self, nums, k):
        maxVal = max(nums)
        count = left = res = 0

        for val in nums:
            if val == maxVal:
                count += 1
            while count >= k:
                if nums[left] == maxVal:
                    count -= 1
                left += 1

            res += left
        return res

class Solution:
    def maximizeSquareHoleArea(
        self, n: int, m: int, hBars: List[int], vBars: List[int]
    ) -> int:
        hBars.sort()
        vBars.sort()

        hcons = {}
        vcons = {}

        i = 0
        while i < len(hBars):
            j = i + 1
            count = 1
            while j < len(hBars):
                if hBars[j] == hBars[j - 1] + 1:
                    count += 1
                else:
                    break
                j += 1
            hcons[hBars[i]] = count
            i = j

        i = 0
        while i < len(vBars):
            j = i + 1
            count = 1
            while j < len(vBars):
                if vBars[j] == vBars[j - 1] + 1:
                    count += 1
                else:
                    break
                j += 1
            vcons[vBars[i]] = count
            i = j

        # print(hcons)
        # print(vcons)

        maxarea = 1
        maxh = max(hcons.values())
        maxv = max(vcons.values())
        maxarea = (min(maxh, maxv) + 1) ** 2
        return maxarea

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        nrows, ncols = len(mat), len(mat[0])

        k %= ncols

        if k == 0:
            return True

        for i, row in enumerate(mat):
            if i % 2 == 0:
                r = row[k:] + row[:k]
                if r != row:
                    return False
            else:
                r = row[-k:] + row[:-k]
                if r != row:
                    return False

        return True

class Solution:
    def placedCoins(self, edges: List[List[int]], cost: List[int]) -> List[int]:
        n = len(cost)
        g = [[] for _ in range(n)]
        for x, y in edges:
            g[x].append(y)
            g[y].append(x)

        ans = [1] * n
        def dfs(x: int, fa: int) -> List[int]:
            a = [cost[x]]
            for y in g[x]:
                if y != fa:
                    a.extend(dfs(y, x))
            a.sort()
            m = len(a)
            if m >= 3:
                ans[x] = max(a[-3] * a[-2] * a[-1], a[0] * a[1] * a[-1], 0)
            if m > 5:
                a = a[:2] + a[-3:]
            return a
        dfs(0, -1)
        return ans

