        i, j, res = s.find(a), s.find(b), []
        while i != -1:
            while 0 <= j < i-k: j = s.find(b,j+1)
            if j == -1:         break
            if j <= i+k:        res.append(i)
            i = s.find(a,i+1)
        return res

