class Solution:
    def maximizeSquareArea(self, m: int, n: int, hFences: List[int], vFences: List[int]) -> int:

        hFences.extend([1,m])
        vFences.extend([1,n])
        hFences.sort()
        vFences.sort()
        ha = set()
        ha.add(m-1)
        mod = 10**9 + 7
        mx = -1
        for i in range(len(hFences)):
            for j in range(i+1,len(hFences)):
                ha.add(hFences[j]-hFences[i])

        for i in range(len(vFences)-1,-1,-1):
            for j in range(0,i+1):
                a = vFences[i]-vFences[j]
                if a in ha:
                    mx = max(mx, (a*a))
                    break

        if mx != -1:
            return mx % mod
        return mx

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)

        j = n - 1
        while j and nums[j-1] < nums[j]:  # determine the start of the last increasing subarray
            j -= 1

        if not j:
            return n * (n + 1) // 2

        k = 1
        while nums[k-1] < nums[k]:  # determine the end of the first increasing subarray
            k += 1

        res = k + n - j
        i = 0

        while i < k and j < n:
            if nums[i] >= nums[j]:
                j += 1
            else:
                res += n - j
                i += 1

        return res + 1  # 1 considers empty array

class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        total = 0

        for n in nums:
            total += n

        while len(nums) > 2:
            maxlen = max(nums)
            total -= maxlen
            if maxlen < total:
                break
            else:
                nums.remove(maxlen)
        if len(nums) == 2:
            return -1
        return sum(nums)

