        return res

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        isum = 0
        psum = {} # v: min prefix sum with end=v
        imax = -10**15
        for v in nums:
            isum += v
            if v-k in psum:
                imax = max(imax,isum-psum[v-k]+v-k)
            if v+k in psum:
                imax = max(imax,isum-psum[v+k]+v+k)
            if v not in psum or psum[v]>isum:
                psum[v] = isum
        #
        if imax==-10**15: return 0
        return imax

class Solution:
    def maximumLength(self, s: str) -> int:
        d = {}
        ls = -1
        ct = 0
        for i in s:
            if i == ls:
                ct += 1
            else:
                d[ls] = d.get(ls, [])
                d[ls].append(ct)
                ct = 1
            ls = i
        d[ls] = d.get(ls, [])
        d[ls].append(ct)
        ans = -1
        for i in d:
            d[i].sort()
            # print(i, d[i])
            if len(d[i]) == 1:
                ans = max(ans, d[i][0] - 2)
            elif len(d[i]) == 2:
                if d[i][0] == d[i][1]:
                    ans = max(ans, d[i][0] - 1)
                else:
                    ans = max(ans, d[i][0], d[i][1]-2)
            else:
                if d[i][-1] == d[i][-2] == d[i][-3]:
                    ans = max(ans, d[i][-1])
                if d[i][-1] == d[i][-2]:
                    ans = max(ans, d[i][-1] - 1)
                else:
                    ans = max(ans, d[i][-1]-2, d[i][-2])
        if ans <= 0:
            return -1
        return ans

class Solution:
    def maximumLength(self, s: str) -> int:
        counter = {}

        l, r = 0, 1

        while r <= len(s):

            if r < len(s) and s[l] == s[r]:
                r += 1

            else:
                substring = s[l:r]

                counter[substring] = counter.get(substring, 0) + 1

                l, r = r, r + 1

        processed_counter = counter.copy()

        for k, v in counter.items():
            if len(k) > 1:
                for i in range(1, len(k)):
                    substring = k[:i]

                    freq = (len(k) - i + 1) * v

                    processed_counter[substring] = processed_counter.get(substring, 0) + freq

        del counter

        max_len = -1

        for k, v in processed_counter.items():
            if v >= 3:
                max_len = max(max_len, len(k))

        return max_len

