class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def kmp(pattern):
            m = len(pattern)
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pattern[i] == pattern[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                elif length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
            return lps

        def find_occurrences(text, pattern):
            lps = kmp(pattern)
            n, m = len(text), len(pattern)
            i = j = 0
            occurrences = []
            while i < n:
                if text[i] == pattern[j]:
                    i += 1
                    j += 1
                    if j == m:
                        occurrences.append(i - j)
                        j = lps[j - 1]
                elif j != 0:
                    j = lps[j - 1]
                else:
                    i += 1
            return occurrences

        resi = find_occurrences(s, a)
        reji = find_occurrences(s, b)

        if not resi or not reji:
            return []

        res = []
        j = 0
        for i in resi:
            while j < len(reji) and reji[j] < i - k:
                j += 1
            if j < len(reji) and abs(i - reji[j]) <= k:
                res.append(i)

        return res

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        counts = {}
        ans = 0
        for w in words:
            cur_length = len(w)
            if cur_length < len(counts):
                for i in range(cur_length):
                    s = w[:i]
                    if s == w[-i:] and s in counts:
                        ans += counts[s]
            else:
                for other in counts:
                    if len(other) >= cur_length:
                        continue
                    if w.startswith(other) and w.endswith(other):
                        ans += counts[other]

            if w in counts:
                ans += counts[w]
                counts[w] += 1
            else:
                counts[w] = 1

        return ans

class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        d = Counter(s)
        l = sorted(d.items(), key=lambda x:x[1])
        l = l[::-1]
        a = l[0][1]
        p = []
        for i in l:
            if d[i[0]]==a:
                p.append(i[0])
            else:
                break
        t = ""
        r = len(s)-1
        while len(p)>0:
            if s[r] in p:
                t+=s[r]
                p.remove(s[r])
            else:
                r-=1
        return t[::-1]

class TrieNode:
        # Initialize your data structure here.
        def __init__(self):
            self.isend = 0
            self.children={}

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self,word):
        res = 0
        node = self.root
        l = len(word)
        for i in range(l):
            pair = (word[i],word[l-i-1])
            if pair not in node.children:
                node.children[pair] = TrieNode()
            node = node.children[pair]
            res += node.isend
        node.isend += 1
        return res


class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        trie = Trie()
        res = 0
        for word in words:
            res += trie.insert(word)
        return res

class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        if abs(x - y) <= 1:
            return [2 * x for x in reversed(range(n))]
        cycle_len = abs(x - y) + 1
        n2 = n - cycle_len + 2
        res = [2 * x for x in reversed(range(n2))]
        while len(res) < n:
            res.append(0)
        res2 = [cycle_len * 2] * (cycle_len >> 1)
        if not cycle_len & 1:
            res2[-1] = cycle_len
        res2[0] -= 2
        for i in range(len(res2)):
            res[i] += res2[i]
        if x > y:
            x, y = y, x
        tail1 = x - 1
        tail2 = n - y
        for tail in (tail1, tail2):
            if not tail:
                continue
            i_mx = tail + (cycle_len >> 1)
            val_mx = 4 * min((cycle_len - 3) >> 1, tail)
            i_mx2 = i_mx - (1 - (cycle_len & 1))
            res3 = [val_mx] * i_mx
            res3[0] = 0
            res3[1] = 0
            if not cycle_len & 1:
                res3[-1] = 0
            for i, j in enumerate(range(4, val_mx, 4)):
                res3[i + 2] = j
                res3[i_mx2 - i - 1] = j
            for i in range(1, tail + 1):
                res3[i] += 2
            if not cycle_len & 1:
                mn = cycle_len >> 1
                for i in range(mn, mn + tail):
                    res3[i] += 2
            for i in range(len(res3)):
                res[i] += res3[i]
        return res

