class Solution:
    def minimumBoxes(self, apple: list[int], capacity: list[int]) -> int:
        m = len(capacity)
        capacity.sort()
        curCapacity = capacity.pop()
        for i in apple:
            curCapacity -= i
            while curCapacity < 0:
                curCapacity += capacity.pop()
        return m-len(capacity)

