class Solution:

	def _rotate_matrix(self, matrix: list[list[int]], k: int):
		for m in zip(*matrix[::-1]):
			yield list(accumulate(m[::-1]))

	def countSubmatrices(self, grid: list[list[int]], k: int) -> int:
		grid_sum = [list(accumulate(g)) for g in grid]

		res = 0
		for g in self._rotate_matrix(grid_sum, 3):
			res += bisect_right(g, k)
		return res

class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        f = [1] + [0] * k
        for x in nums:
            for j in range(k, -1, -1):
                f[j] = (f[j] * 2 + (f[j - x] if j >= x else 0)) % 1_000_000_007
        return f[k]

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        ans = ''
        for i,l in enumerate(s):
            if l == 'a':
                ans += 'a'
                continue
            if k == 0:
                break
            v = ord(l) - ord('a')
            change = v
            if v > 13:
                change = 26 - v
            if change <= k:
                k -= change
                ans += 'a'
            else:
                ans += chr(ord(l) - k)
                k = 0
        if len(ans) == len(s):
            return ans    
        return ans + s[i:]

