class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        cid = 0
        count = 0
        out = []
        dic = {}

        for i in range(len(nums)):
            if nums[i] not in dic:
                dic[nums[i]] = freq[i]
            else:
                dic[nums[i]] += freq[i]

            if cid != nums[i] and dic[nums[i]] > count:
                cid = nums[i]
                count = dic[nums[i]]
            elif cid == nums[i]:
                count = dic[nums[i]]

            if cid == nums[i] and freq[i] < 0:
                for k in dic:
                    if dic[k] > count:
                        cid = k
                        count = dic[k]

            out.append(count)

        return out

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        N = len(nums)
        INF = float('inf')

        dp = [INF] * (N + 1)
        dp[0] = 0
        for j, av in enumerate(andValues):
            dp2 = [INF] * (N + 1)

            left = 0

            current_min = INF

            current_and = -1

            stack = []
            for i, v in enumerate(nums):
                next_and = (current_and & v)
                if next_and == av:


                    stack_len = len(stack)
                    del stack[:]
                    and2 = -1
                    for l2 in range(i, left - 1, -1):
                        next_and2 = and2 & nums[l2]
                        if next_and2 == av:
                            break
                        else:

                            stack.append(next_and2)
                            and2 = next_and2

                    for k in range(left - stack_len, l2 + 1):
                        current_min = min(current_min, dp[k])

                    left = i + 1
                    next_and = -1
                elif (next_and & av) != av:

                    next_and = -1
                    left = i + 1
                    current_min = INF
                    del stack[:]
                else:

                    while stack and (stack[-1] & next_and) == av:
                        current_min = min(current_min, dp[left - len(stack)])
                        stack.pop()
                current_and = next_and
                dp2[i + 1] = current_min + v
            #print(dp2)
            dp = dp2
        if dp[-1] == INF:
            return -1
        else:
            return dp[-1]

