"""
An integer divisible by the sum of its digits is said to be a Harshad number. You are given an integer x. Return the sum of the digits of x if x is a Harshad number, otherwise, return -1.
"""
class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:

        # Compute the sum of the digits of x
        digit_sum = 0
        temp = x
        while temp != 0:
            digit_sum += temp % 10
            temp //= 10

        # Return the sum of digits if x is a Harshad number, -1 otherwise
        if x % digit_sum == 0:
            return digit_sum
        else:
            return -1

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        inc = 1
        dec = 1
        answer = 1
        for i in range(1, len(nums)):
            if nums[i-1] < nums[i]:
                inc += 1
                dec = 1
            elif nums[i-1] > nums[i]:
                dec += 1
                inc = 1
            else :
                dec = 1
                inc = 1
            answer = max(inc, dec, answer)
        return answer

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
#         @cache
#         def isPrime(n: int) -> bool:
#             if n <= 1:
#                 return False
#             if n <= 3:
#                 return True
#             if n % 2 == 0 or n % 3 == 0:
#                 return False

#             i = 5
#             while i * i <= n:
#                 if n % i == 0 or n % (i + 2) == 0:
#                     return False
#                 i = i + 6

#             return True

#         nums = filter(isPrime, nums)
#         return max(nums or [0]) - min(nums or [0])
        @cache
        def isPrime(n: int) -> bool:
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False

            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i = i + 6

            return True

        i, j = 0, len(nums) - 1
        while True:
            if isPrime(nums[i]):
                break
            i += 1
        while j > i:
            if isPrime(nums[j]):
                break
            j -= 1

        return j - i

