class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def sum_e(k: int) -> int:
            ans = n = cnt1 = sum_i = 0
            for i in range((k+1).bit_length()-1, 0, -1):
                c = (cnt1<<i) + (i<<(i-1))
                if c <= k:
                    k -= c
                    ans += (sum_i<<i) + ((i*(i-1)//2)<<(i-1))
                    sum_i += i
                    cnt1 += 1
                    n |= 1 << i
            if cnt1 <= k:
                k -= cnt1
                ans += sum_i
                n |= 1
            for _ in range(k):
                lb = n & -n
                ans += lb.bit_length()-1
                n ^= lb
            return ans
        return [pow(2, sum_e(r+1)-sum_e(l), mod) for l, r, mod in queries]

