        remainders: List[int] = [0 for _ in range(24)]

        for hour in hours:
            remainders[hour % 24] += 1

        total: int = 0
        for i in range(1, 12):
            total += remainders[i] * remainders[24 - i]

        total += comb(remainders[0], 2)
        total += comb(remainders[12], 2)

        return total

