class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Step 1: collect all positions where nums[i] == x
        pos_list = []
        for i, val in enumerate(nums):
            if val == x:
                pos_list.append(i)

        # Step 2: answer each query in O(1)
        ans = []
        total = len(pos_list)
        for q in queries:
            if 1 <= q <= total:
                ans.append(pos_list[q - 1])
            else:
                ans.append(-1)
        return ans

