class Solution:
    def compressedString(self, word: str) -> str:
        if not word:
            return ""

        comp = []
        count = 1
        current_char = word[0]

        for char in word[1:]:
            if char == current_char and count < 9:
                count += 1
            else:
                comp.append(str(count))
                comp.append(current_char)
                current_char = char
                count = 1

        # Append the last sequence
        comp.append(str(count))
        comp.append(current_char)

        return ''.join(comp)

