            if x!=0:
                x = 2 if x%2==0 else 1
            count_letters.append(x)

        return sum(count_letters)

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        fs = {}
        records = [[0] * 3 for _ in range(k + 1)]
        for x in nums:
            if x not in fs:
                fs[x] = [0] * (k + 1)
            f = fs[x]
            for j in range(k, -1, -1):
                f[j] += 1
                if j > 0:
                    mx, mx2, num = records[j - 1]
                    f[j] = max(f[j], (mx if x != num else mx2) + 1)

                # records[j] 维护 fs[.][j] 的 mx, mx2, num
                v = f[j]
                p = records[j]
                if v > p[0]:
                    if x != p[2]:
                        p[2] = x
                        p[1] = p[0]
                    p[0] = v
                elif x != p[2] and v > p[1]:
                    p[1] = v
        return records[k][0]

class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        r = {e: c for e,c in requirements}
        c = max(r.values())
        max_end = max(r)
        mod = 10 ** 9 + 7
        dp = [1] + [0] * c
        for i in range(max_end + 1):
            dp2 = [0] * (c + 1)
            if i in r:
                dp2[r[i]] = sum(dp[max(0, r[i] - i): r[i] + 1]) % mod
            else:
                for j in range(c + 1):
                    dp2[j] = dp[j]
                    if j: dp2[j] += dp2[j - 1]
                    if j - i > 0: dp2[j] -= dp[j - i - 1]
            dp = dp2
        res = sum(dp) % mod
        for i in range(max_end + 1, n):
            res = res * (i + 1) % mod
        return res

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])

        vertical, horizontal = 0, 0 
        v_set, h_set = set(), set()
        for r in range(rows):
            boolean = True 
            for c in range(cols):
                if grid[r][c]:
                    boolean = False 
                    break
            v_set.add(r)
            if not boolean:
                break

            vertical += 1 

        for r in range(rows - 1, -1, -1):
            boolean = True 
            if r in v_set:
                break
            for c in range(cols):
                if grid[r][c]:
                    boolean = False 
                    break
            if not boolean:
                break
            vertical += 1 

        for c in range(cols):
            boolean = True 
            for r in range(rows):
                if grid[r][c]:
                    boolean = False 
                    break
            h_set.add(c)
            if not boolean:
                break
            horizontal += 1 

        for c in range(cols - 1, -1, -1):
            if c in h_set:
                break
            boolean=True 
            for r in range(rows):
                if grid[r][c]:
                    boolean=False
                    break
            if not boolean:
                break
            horizontal += 1

        area = (rows - vertical) * (cols - horizontal)
        return area

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int]) -> int:
        n = len(colors)

        count = 0
        for i in range(n):
            if colors[i] == colors[(i+2)%n] and colors[(i+1)%n] != colors[i]:
                count+=1
        return count

class Solution:
    def maximumTotalCost(self, nums: List[int]) -> int:

        dp1 = dp2 = nums.pop(0)                     # <-- 1)

        for n in nums:
            dp1, dp2 = max(dp1, dp2) + n, dp1 - n   # <-- 2)

        return max(dp1, dp2)                        # <-- 3)

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        ci = None
        r = 0
        s = 0
        j = None
        ss = None
        for i, n in enumerate(nums):
            if n & k == k:
                if ci is not None:
                    s = s & n
                    if s == k:
                        r += i - ci
                        if j is None:
                            j = i - 1
                            ss = n
                            while j >= 0 and ss & nums[j] != k:
                                ss = ss & nums[j]
                                j -= 1
                            r -= i - j - 1
                        # j = None
                        else:
                            if n & ss != k:
                                ss = ss & n
                                r -= i - j - 1
                            else:
                                j = i - 1
                                ss = n
                                while j >= 0 and ss & nums[j] != k:
                                    ss = ss & nums[j]
                                    j -= 1
                                r -= i - j - 1

                    if n == k:
                        r += 1
                        j = None
                else:
                    ci = i
                    s = n
                    if n == k:
                        r += 1
                    j = None
            else:
                ci = None
                s = 0
                j = None
        return r

