class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        flips = 0

        for i in range(n-2):
            if nums[i]==0:
                flips += 1
                nums[i] = 1 - nums[i]
                nums[i+1] = 1 - nums[i+1]
                nums[i+2] = 1 - nums[i+2]

        if nums[-2] == 1 and nums[-1] == 1:
            return flips
        else:
            return -1

class Solution:
