class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], k: int) -> int:
        n = len(colors)

        idx = None

        for i in range(n - 1):
            if colors[i] == colors[i + 1]:
                idx = i + 1

                break

        if idx == None: 
            if colors[0] != colors[-1]:
                return n 

            else: 
                return max(n - k + 1, 0)


        colors = colors[idx: ] + colors[: idx]

        prev = 0 
        cnt = 0

        ans = 0 

        for color in colors + [colors[-1]]: 
            if color != prev: 
                cnt += 1

            else: 
                if cnt >= k: 
                    ans += (cnt - k + 1)

                cnt = 1 

            prev = color 

        return ans

class Solution:
    def getSmallestString(self, s: str) -> str:
        s = list(s)
        l, r = 0, 1
        while r < len(s):
            n1, n2 = int(s[l]), int(s[r])
            if ((n1 + n2 ) % 2 == 0 
                and n1 > n2):
                s[l], s[r] = s[r], s[l]
                break 
            l += 1
            r += 1
        return ''.join(s)

class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start = sorted(start)
        n = len(start)
        hi = (start[-1] + d - start[0]) // (len(start)-1)
        lo = 0

        def test(x, jmp):
            cur = start[jmp]
            last_jump = 0
            for i in range(jmp+1,n):
                s = start[i]
                cur += x
                if cur > s+d:
                    return False, last_jump
                if s > cur:
                    last_jump = i
                    cur = s
            return True, last_jump

        last_jump = 0
        passes, last_jump = test(hi, last_jump)
        if passes:
            return hi

        m = (lo + hi) //2
        while lo < hi:
            #print(lo, m , hi)
            passes, maybe_jump = test(m, last_jump)
            if passes:
                lo = m
            else:
                hi = m-1
                last_jump = maybe_jump
            m = lo + (hi+1 - lo) * 1//2
        return m

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        odd, even, alternating = 0, 0, 0
        expected_sign = nums[0] % 2
        for num in nums:
            if num % 2 == 0:
                even += 1
            else:
                odd += 1
            if num % 2 == expected_sign:
                alternating += 1
                expected_sign = 1 - expected_sign
        return max(odd, even, alternating)

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        nums = [num % k for num in nums]
        def check(a, b):
            alternating = (num for num in nums if num == a or num == b)
            return 1 + sum([1 for a, b in pairwise(alternating) if a != b])

        counts = sorted([(count, val) for val, count in Counter(nums).items()], reverse=True)
        best = counts[0][0]
        for i in range(len(counts)-1):
            countA, a = counts[i]
            for j in range(i+1, len(counts)):
                countB, b = counts[j]
                if countA + countB <= best:
                    break
                best = max(best, check(a, b))
        return best

