        y_col_sum = [0]*n
        ct = 0
        for i in range(m):
            curx = 0
            cury = 0
            for j in range(n):
                if grid[i][j]=="X":
                    x_col_sum[j]+=1
                if grid[i][j]=="Y":
                    y_col_sum[j]+=1
