class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        hor_cuts = ver_cuts = 1
        cut_costs = [(c, 0) for c in horizontalCut]
        cut_costs += [(c, 1) for c in verticalCut]

        cut_costs.sort(reverse=True)

        # print(cut_costs)

        total = 0

        for c, t in cut_costs:
            if(t == 0):
                total += c * ver_cuts
                hor_cuts += 1
            else:
                total += c * hor_cuts
                ver_cuts += 1

        return total

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        l, r = 0, (mountainHeight * (mountainHeight+1))//2 * max(workerTimes)

        def check(v):
            res = 0 
            v2 = v*2 
            for i in workerTimes:
                ll, rr = 0,  mountainHeight
                while ll< rr:
                    tmp = (ll+rr+1)>>1
                    if (i*(1+tmp)*tmp) > v2:
                        rr = tmp - 1
                    else:
                        ll = tmp
                res += ll 
                if res >= mountainHeight:
                    return True 
            return False

        while l<r:
            mid = (l+r)>>1
            if check(mid):
                r = mid 
            else:
                l = mid+1 
        return l

class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums) // 2
        diffs = Counter(abs(nums[x] - nums[2*n - x - 1]) for x in range(n))
        min_steps = 2*n
        sdiffs = sorted([(x, y) for x, y in diffs.items()], key = lambda x: -x[1])

        for d, x in sdiffs:
            if d <= (k + 1) // 2: # 01234 -> 2 012345 -> 3
                if min_steps > n - x:
                    min_steps = n - x
            else: 
                if min_steps > n - x:
                    steps = 0
                    for i in range(n):
                        if abs(nums[i] - nums[2*n - i - 1]) != d:
                            if nums[i] + d <= k or nums[i] - d >= 0 or nums[2*n - i - 1] + d <= k or nums[2*n - i - 1] - d >= 0:
                                steps += 1
                            else:
                                steps += 2
                    if min_steps > steps:
                        min_steps = steps

        return min_steps

class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        v_cuts, h_cuts = [0]*1001, [0]*1001
        v_parts, h_parts = 1, 1
        ans = 0
        for h in horizontalCut:
            h_cuts[h] += 1
        for v in verticalCut:
            v_cuts[v] += 1
        for i in range(1000, 0, -1):
            ans += h_cuts[i] * v_parts * i
            h_parts += h_cuts[i]
            ans += v_cuts[i] * h_parts * i
            v_parts += v_cuts[i]
        return ans

class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        d = {}
        left = 0
        res = 0

        for x in s:
            d[x] = d.get(x, 0) + 1

            while d[x] == k:
                d[s[left]] -= 1
                left += 1
            res += left
        return res

mx = int(sqrt(10**9)) - 14
sp = []


class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        if not sp:
            sieve = [False] * mx
            for i in range(2, mx):
                if not sieve[i]:
                    for j in range(i * i, mx, i):
                        sieve[j] = True
            for i in range(2, mx):
                if not sieve[i]:
                    sp.append(i * i)

        lo, hi = bisect_left(sp, l), bisect_right(sp, r)
        return (r - l + 1) - (hi - lo)

def cardinality(bitset: int):
    ones_count = 0
    while bitset:
        ones_count += (bitset & 1)
        bitset >>= 1
    return ones_count

class Solution:
    def minChanges(self, n: int, k: int) -> int:
        a = (n ^ k)
        b = a & n
        if a == b:
            return cardinality(a)
        else:
            return -1

