class Solution:
    def maxScore(self, a: List[int], b: List[int]) -> int:
        L = len(b)
        w,x,y,z = -inf,-inf,-inf,-inf
        for c in b:
            if a[3]*c+y > z:
                z = a[3]*c+y
            if a[2]*c+x > y:
                y = a[2]*c+x
            if a[1]*c+w > x:
                x = a[1]*c+w
            if a[0]*c > w:
                w = a[0]*c
        return z

