def winningPlayerCount(n: int, pick: List[List[int]]) -> int:
    play = defaultdict(lambda: defaultdict(int))
    for p, color in pick:
        play[p][color] += 1
    win = 0
    for p in range(n):
        if p == 0 and play[p]:
            win += 1
        elif any(count > p for count in play[p].values()):
            win+= 1
    return win
