class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        if k == 1:
            return nums
        n = len(nums)
        ans = [-1] * (n - k + 1)
        consecutive = 1
        for i in range(1, n):
            if nums[i] == nums[i - 1] + 1:
                consecutive += 1
            else:
                consecutive = 1
            if consecutive >= k:
                ans[i - k + 1] = nums[i]
        return ans

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        flips = 0
        for i in range(m//2):
            for j in range(n//2):
                sum = grid[i][j] + grid[m-1-i][j] + grid[i][n-1-j] + grid[m-1-i][n-1-j]
                if sum == 1 or sum == 3:
                    flips += 1
                elif sum == 2:
                    flips += 2

        total1, flips1 = 0, 0
        if m%2:
            i = m//2
            for j in range(n//2):
                if grid[i][j] != grid[i][n-1-j]:
                    flips1 += 1
                elif grid[i][j] == 1:
                    total1 += 2

        if n%2:
            j = n//2
            for i in range(m//2):
                if grid[i][j] != grid[m-1-i][j]:
                    flips1 += 1
                elif grid[i][j] == 1:
                    total1 += 2

        flips += flips1
        if total1%4 == 2:
            if not flips1:
                flips += 2

        if m%2 and n%2 and grid[m//2][n//2] == 1:
            flips += 1

        return flips

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        ctr_A = 0
        ctr_B = 0
        for i in range(len(energyDrinkA)):
            temp_A = energyDrinkA[i] + ctr_A
            if temp_A < ctr_B:
                temp_A = ctr_B
            temp_B = energyDrinkB[i] + ctr_B
            if temp_B < ctr_A:
                temp_B = ctr_A
            ctr_B = temp_B
            ctr_A = temp_A
        if ctr_A > ctr_B:
            return ctr_A
        else:
            return ctr_B

from bisect import bisect_left
def add(idx, work, j, ok, diff):
    skip, n = False, len(work)
    while j != n:
        if work[j] not in ok:
            if skip: return
            skip = True
        y = work[j] - work[j - 1]
        j += 1
        if y < 3: continue
        idx[y] = idx.get(y, 0) + diff
        if not idx[y]: idx.pop(y)
class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n0 = max (i for i,xs in enumerate([[1]] + queries) if xs[0] == 1 )
        if not n0: return []
        buf, idx, n = [], {}, len(colors)
        work = [ i for i,(x,y) in enumerate(zip(colors, colors[1:]), 1) if x == y ]
        for x,y in zip(work, work[1:]):
            y -= x
            if 2 < y: idx[y] = idx.get(y, 0) + 1
        colors.append(-1)
        for xs in queries[:n0]:
            if xs[0] == 1:
                k0 = xs[1] - 1
                if colors[0] == colors[-2]:
                    if work:
                        now = sum( max(k - k0, 0) * v for k,v in idx.items() )
                        now += max(work[0] - k0, 0) + max(n - work[-1] - k0, 0)
                    else: now = n - k0
                elif work:
                    now = sum( max(k - k0, 0) * v for k,v in idx.items() )
                    now += max(work[0] + n - work[-1] - k0, 0)
                else: now = n
                buf.append(now)
                continue
            i, x0 = xs[1:]
            if colors[i] == x0: continue
            j, ok = bisect_left(work, i), {i, i + 1}
            add(idx, work, j, ok, -1)
            if colors[i] == colors[i-1]: work.pop(j)
            if colors[i] == colors[i+1]: work.pop(j)
            colors[i] = x0
            if colors[i] == colors[i+1]: work.insert(j, i + 1)
            if colors[i] == colors[i-1]: work.insert(j, i)
            add(idx, work, j, ok, 1)
        return buf

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        max_so_far = 0
        total_score = 0

        for num in nums[:-1]: 
            max_so_far = max(max_so_far, num)
            total_score += max_so_far

        return total_score

