class Solution:
    def countPairs(self, nums: List[int]) -> int:

        d, ans = defaultdict(list), 0

        mx = int(log10(max(nums)))+1
        nums = map(lambda x: (str(x).rjust(mx, '0')), nums)

        for num in nums:
            d[''.join(sorted(num))]. append(num)

        for key in d:
            for str1, str2 in combinations(d[key],2):
             if sum(c1 != c2 for c1, c2 in zip(str1, str2)) < 3:
                ans+= 1

        return ans

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 1_000_000_007

        n = len(nums)
        a1, a2 = 0, nums[0]
        for num in nums:
            if num < a1:
                return 0
            if num >= a1 + a2:
                a1 = num - a2  # a1 + (num - (a1+a2))
            a2 = num - a1

        return comb(n+a2, a2) % MOD

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:

        n, mn = len(nums), nums.pop(0)
        num1, num2 = 0, mn

        for num in nums:
            if num < num1: return 0

            if num > num1 + num2: 
                num1 = num - num2  

            num2 = num - num1

            if num2 < mn: mn = num2

        return comb(n + mn, mn) % 1_000_000_007

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        sol=""
        for i in range(0,len(s)-k+1,k):
            p=s[i:i+k]
            q=0
            for j in p:
                q+=ord(j)-97
            q=q%26
            q=q+97
            sol+=chr(q)
        return(sol)

