        def dfs(i=0, h=0, mask=0, mask2=0, ans=0):
            if h == 3:
                return ans

            ret = -math.inf
            for k in range(i, len(B)):
                v, x, y = B[k]

                if (3 - h) * v + ans <= ret:
                    return ret

                if not mask & x and not mask2 & y:
                    ret = max(ret, dfs(k, h + 1, mask | x, mask2 | y, ans + v))

            return ret

        return dfs()



