class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count_0 = count_1 = 0
        left = 0
        result = 0

        for right in range(n):
            if s[right] == '0':
                count_0 += 1
            else:
                count_1 += 1

            while count_0 > k and count_1 > k:
                if s[left] == '0':
                    count_0 -= 1
                else:
                    count_1 -= 1
                left += 1

            result += right - left + 1

        return result

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])
        c_c = [[] for _ in range(n)]
        for i,r in enumerate(board):
            c_r = []
            for j,v in enumerate(r):
                x = (v,i,j)
                if len(c_r)<3:
                    heappush(c_r, x)
                else:
                    heappushpop(c_r, x)
            for c in c_r:
                j = c[2]
                if len(c_c[j])<3:
                    heappush(c_c[j], c)
                else:
                    heappushpop(c_c[j], c)
        can = []
        for ls in c_c:
            for c in ls:
                if len(can)<9:
                    heappush(can, c)
                else:
                    heappushpop(can, c)
        ans = -float("inf")
        for x,y,z in combinations(can, 3):
            if len({x[1], y[1], z[1]})==3 and len({x[2], y[2], z[2]})==3:
                ans = max(ans, x[0]+y[0]+z[0])
        return ans

