        m, n = len(word1), len(word2)
        last, j = [-1]*n, n-1

        for i in range(m-1, -1, -1):
            if word1[i] == word2[j]:
                last[j] = i
                j -= 1
            if j < 0: 
                break

        j, change, ans = 0, False, []
        for i in range(m):
            if word1[i] == word2[j]:
                ans.append(i)
                j += 1
            elif not change and (j == n-1 or i < last[j+1]):
                change = True
                ans.append(i)
                j += 1
            if j == n:
                return ans
        return []


