def spd_to(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False

    spd = [None] * (n + 1)

    for i in range(2, n + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                if is_prime[j]:
                    spd[j] = i
                is_prime[j] = False
    return spd
