class Solution:
    def possibleStringCount(self, word: str, k: int) -> int:
        MOD = 10**9 + 7
        # run-rate encode word
        c_list = []
        prev = None
        count = 0
        for ch in word:
            if ch == prev:
                count += 1
            else:
                if prev is not None:
                    c_list.append(count)
                prev = ch
                count = 1
        if prev is not None:
            c_list.append(count)
        m = len(c_list)
        # total combinations without length constraint
        total = 1
        for c in c_list:
            total = total * c % MOD
        # if minimum possible length m >= k, all combinations valid
        if m >= k:
            return total
        # count invalid combinations where sum L_i' <= k-1 - m
        Kp = k - 1 - m
        # dp[j]: number of ways for sum of extra presses j
        dp = [0] * (Kp + 1)
        dp[0] = 1
        for c in c_list:
            ai = c - 1
            # prefix sums for efficient convolution
            pref = [0] * (Kp + 1)
            pref[0] = dp[0]
            for j in range(1, Kp + 1):
                pref[j] = (pref[j-1] + dp[j]) % MOD
            newdp = [0] * (Kp + 1)
            for j in range(Kp + 1):
                if j - ai - 1 >= 0:
                    newdp[j] = (pref[j] - pref[j - ai - 1]) % MOD
                else:
                    newdp[j] = pref[j]
            dp = newdp
        invalid = sum(dp) % MOD
        return (total - invalid + MOD) % MOD

class Solution:
    def maxIncreasingSubarrays(self, nums: List[int]) -> int:
        single = 0
        double = 0
        x = -1
        y = -1
        z = -1
        s = 0
        d = 0
        for i in range(len(nums) - 1):
            if nums[i] >= nums[i+1]:
                x, y, z = y, z, i
                s = z - y
                d = min(z - y, y - x)
                if s > single:
                    single = s
                if d > double:
                    double = d
        x, y, z = y, z, len(nums) - 1
        single = max(single, z - y)
        double = max(double, min(z - y, y - x))
        return max(single // 2, double)

