from typing import List
import bisect

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:


        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            parent[find(x)] = find(y)

        nums = sorted(list(set(nums)))
        if nums[0] == 1:
            cutoff = bisect.bisect_left(nums, threshold + 1)
            return len(nums) - cutoff + 1
        n = len(nums)
        parent = list(range(n))
        arr = [-1]*(threshold+1)
        for node, val in enumerate(nums):
            for u in range(val, threshold+1, val):
                if arr[u] == -1:
                    arr[u] = find(node)
                    continue

                root_cur = find(node)
                root_target = arr[u]
                if root_cur != root_target:
                    union(root_cur, root_target)
                    arr[u] = root_target        

        comps = set()
        for i in range(n):
            comps.add(find(i))
        return len(comps)

class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        if numFriends == 1:
            return word

        window = len(word) - numFriends + 1
        res = -1
        maxScore = ""
        for idx in range(len(word)):
            if word[idx: idx + window] > maxScore:
                maxScore = word[idx: idx + window]
                res = idx
        return word[res: res + window]

