class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        def solve(d):
            rem_cnt = defaultdict(int)
            rem_cnt[0] = 1
            pref_rem = 0
            res = 0
            for i, c in enumerate(s):
                nrc = defaultdict(int)
                for rem, cnt in rem_cnt.items():
                    nrc[rem*10 % d] += cnt
                pref_rem = (pref_rem * 10 + int(c)) % d

                if int(c) == d:
                    res += nrc[pref_rem]

                rem_cnt = nrc
                rem_cnt[pref_rem] += 1

            return res
        res = 0
        for d in range(1, 10):
            res += solve(d)

        return res

class Solution:
    def gcd(self, a: int, b: int) -> int:
        if a < b:
            a, b = b, a
        while b > 0:
            r = a % b
            a = b
            b = r
        return a

    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)

        left = 0
        right = 1
        max_len = 2
        while right < n:
            right_num = nums[right]
            for i in range(right - 1, left - 1, -1):
                if self.gcd(right_num, nums[i]) != 1:
                    new_len = right - left   
                    if max_len < new_len:
                        max_len = new_len
                    #max_len = max(max_len, right - left)
                    left = i + 1
                    break
            right += 1
        new_len = right - left   
        if max_len < new_len:
            max_len = new_len
        return max_len



